WITH acct AS (
  SELECT id FROM accounts WHERE name='Mayer & Co'
), c_emails AS (
  SELECT email FROM contacts WHERE account_id=(SELECT id FROM acct)
)
SELECT MAX(sent_at) AS last_heard_at
FROM fetched_emails
WHERE sender IN (SELECT email FROM c_emails)
   OR recipient IN (SELECT email FROM c_emails);

WITH acct AS (
  SELECT id FROM accounts WHERE name='Mayer & Co'
), c_emails AS (
  SELECT email FROM contacts WHERE account_id=(SELECT id FROM acct)
)
SELECT MIN(e.start_time) AS next_meeting_start_time
FROM fetched_events e
WHERE EXISTS (
  SELECT 1 FROM c_emails ce
  WHERE e.attendees LIKE '%' || ce.email || '%'
)
  AND e.start_time >= datetime('now');

WITH acct AS (
  SELECT id FROM accounts WHERE name='Mayer & Co'
), c_emails AS (
  SELECT email FROM contacts WHERE account_id=(SELECT id FROM acct)
)
SELECT CASE WHEN EXISTS (
  SELECT 1
  FROM fetched_events e
  WHERE EXISTS (
    SELECT 1 FROM c_emails ce
    WHERE e.attendees LIKE '%' || ce.email || '%'
  )
  AND e.start_time >= datetime('now')
) THEN 1 ELSE 0 END AS is_meeting_scheduled;
